<?php

namespace App\External\Documents\ActionCenter\Excel;

use Maatwebsite\Excel\Concerns\FromArray;
use Maatwebsite\Excel\Concerns\ShouldAutoSize;
use Maatwebsite\Excel\Concerns\WithCustomStartCell;
use Maatwebsite\Excel\Concerns\WithEvents;
use Maatwebsite\Excel\Concerns\WithHeadings;
use Maatwebsite\Excel\Events\AfterSheet;
use Maatwebsite\Excel\Events\BeforeSheet;
use PhpOffice\PhpSpreadsheet\Cell\Coordinate;
use PhpOffice\PhpSpreadsheet\Style\Alignment;
use PhpOffice\PhpSpreadsheet\Style\Border;
use PhpOffice\PhpSpreadsheet\Style\Fill;

class ActionCenterReportExport implements FromArray, ShouldAutoSize, WithCustomStartCell, WithEvents, WithHeadings
{
    public function __construct(
        private readonly string $title,
        private readonly string $municipalityName,
        private readonly string $generatedBy,
        private readonly string $filterSummary,
        private readonly array $headings,
        private readonly array $rows,
        private readonly array $currencyColumns = [],
    ) {}

    public function startCell(): string
    {
        return 'A6';
    }

    public function headings(): array
    {
        return $this->headings;
    }

    public function array(): array
    {
        return $this->rows;
    }

    public function registerEvents(): array
    {
        return [
            BeforeSheet::class => function (BeforeSheet $event): void {
                $sheet = $event->sheet->getDelegate();
                $lastColumn = $this->lastColumn();

                $sheet->mergeCells("A1:{$lastColumn}1");
                $sheet->setCellValue('A1', $this->title);
                $sheet->setCellValue('A2', 'Municipality');
                $sheet->setCellValue('B2', $this->municipalityName);
                $sheet->setCellValue('A3', 'Generated');
                $sheet->setCellValue('B3', now()->format('Y-m-d H:i:s'));
                $sheet->setCellValue('A4', 'Generated by');
                $sheet->setCellValue('B4', $this->generatedBy);
                $sheet->setCellValue('A5', 'Filters');
                $sheet->setCellValue('B5', $this->filterSummary);

                $sheet->getStyle('A1')->getFont()->setBold(true)->setSize(16)->setColor(new \PhpOffice\PhpSpreadsheet\Style\Color('FF0F172A'));
                $sheet->getStyle('A2:A5')->getFont()->setBold(true)->setColor(new \PhpOffice\PhpSpreadsheet\Style\Color('FF475569'));
                $sheet->getRowDimension(1)->setRowHeight(26);
            },
            AfterSheet::class => function (AfterSheet $event): void {
                $sheet = $event->sheet->getDelegate();
                $headingRow = 6;
                $lastColumn = $this->lastColumn();
                $lastRow = max($headingRow, $headingRow + count($this->rows));

                $sheet->freezePane('A7');
                $sheet->setAutoFilter("A{$headingRow}:{$lastColumn}{$lastRow}");
                $sheet->getStyle("A{$headingRow}:{$lastColumn}{$headingRow}")->applyFromArray([
                    'font' => ['bold' => true, 'color' => ['argb' => 'FFFFFFFF']],
                    'fill' => [
                        'fillType' => Fill::FILL_SOLID,
                        'startColor' => ['argb' => 'FF0F172A'],
                    ],
                    'alignment' => ['vertical' => Alignment::VERTICAL_CENTER],
                ]);
                $sheet->getRowDimension($headingRow)->setRowHeight(24);
                $sheet->getStyle("A{$headingRow}:{$lastColumn}{$lastRow}")
                    ->getBorders()
                    ->getAllBorders()
                    ->setBorderStyle(Border::BORDER_HAIR)
                    ->getColor()
                    ->setARGB('FFE2E8F0');

                foreach ($this->currencyColumns as $column) {
                    $sheet->getStyle("{$column}7:{$column}{$lastRow}")
                        ->getNumberFormat()
                        ->setFormatCode('"PHP" #,##0.00');
                }

                $sheet->getStyle("A7:{$lastColumn}{$lastRow}")->getAlignment()->setVertical(Alignment::VERTICAL_TOP);
            },
        ];
    }

    private function lastColumn(): string
    {
        return Coordinate::stringFromColumnIndex(count($this->headings));
    }
}
